def lpHaarSystemSet (𝕜 : Type*) [RCLike 𝕜] (p : BanachExponent) : Set (IntervalLp 𝕜 p) :=
  insert (lpHaarCellVector 𝕜 p 0 0)
    (Set.range (fun nk : Σ n : ℕ, Fin (2 ^ n) => lpHaarDyadic 𝕜 p nk.1 nk.2))

